//! Agents generated by `#[component(agent(..))]`, run through the exported
//! component with `veryl_component::testing::MockSim`.

use std::cell::RefCell;
use std::rc::Rc;

use verald_tb_core::Methodology;
use verald_tb_core::prelude::*;
use verald_tb_runtime::{Clock, TestError};
use veryl_component::Value;
use veryl_component::testing::MockSim;

thread_local! {
    static LOG: RefCell<Vec<String>> = const { RefCell::new(Vec::new()) };
}

fn log(entry: impl Into<String>) {
    LOG.with(|l| l.borrow_mut().push(entry.into()));
}

fn take_log() -> Vec<String> {
    LOG.with(|l| std::mem::take(&mut *l.borrow_mut()))
}

#[sequence_item(handle = TxRef)]
#[derive(Clone, Debug, Default)]
struct Tx {
    addr: u32,
}

struct Config {
    clk: Clock,
    active: bool,
}

impl AgentConfig for Config {
    fn active(&self) -> bool {
        self.active
    }
}

type Context = InstanceContext<Config>;

/// Sees a request at each edge and publishes it, and a transfer for it.
#[component(monitor)]
struct TxMonitor {
    #[context]
    context: Context,
    #[analysis_port]
    port: AnalysisPort<TxRef>,
    #[request_port]
    requests: AnalysisPort<u32>,
}

#[component(monitor)]
impl Component for TxMonitor {
    type Context = Context;

    fn build(_scope: &Scope, context: Context) -> Result<Self, TestError> {
        Ok(TxMonitor {
            context,
            port: AnalysisPort::new(),
            requests: AnalysisPort::new(),
        })
    }

    async fn run(&mut self, _run_context: &mut RunContext) -> Result<(), TestError> {
        let clk = self.context().config().clk;
        let mut n = 0;
        loop {
            clk.edge().await;
            n += 1;
            self.requests.write(&n);
            self.port.write(&Tx { addr: n }.into());
        }
    }
}

#[component(driver)]
struct TxDriver {
    #[context]
    context: Context,
    #[seq_item_port]
    port: SeqItemPort<Tx>,
}

#[component(driver)]
impl Component for TxDriver {
    type Context = Context;

    fn build(_scope: &Scope, context: Context) -> Result<Self, TestError> {
        Ok(TxDriver {
            context,
            port: SeqItemPort::new(),
        })
    }

    async fn run(&mut self, _run_context: &mut RunContext) -> Result<(), TestError> {
        loop {
            let item = self.port.get_next_item().await?;
            log(format!("drive {}", item.borrow().addr));
            self.port.item_done()?;
        }
    }
}

#[component(sequencer(item = Tx, request = u32))]
struct TxSequencer {
    #[context]
    context: Context,
}

/// Answers each request with a transfer to its address.
#[sequence(sequencer = TxSequencer)]
struct Responder {}

impl Sequence for Responder {
    async fn body(&mut self) -> Result<(), TestError> {
        loop {
            let request = self.get_request().await;
            let mut item = Tx { addr: request * 10 };
            self.start_item(&mut item).await?;
            self.finish_item(item).await?;
        }
    }
}

#[component(agent(
    monitor = TxMonitor,
    sequencer = TxSequencer,
    driver = TxDriver,
    reactive,
    post_build
))]
struct TxAgent {
    /// What the monitor published, collected by the agent's own addition.
    seen: Rc<RefCell<Vec<u32>>>,
}

impl TxAgent {
    fn post_build(&mut self, _scope: &Scope) -> Result<(), TestError> {
        let seen = self.seen.clone();
        self.analysis_port()
            .subscribe(move |tx| seen.borrow_mut().push(tx.borrow().addr));
        Ok(())
    }
}

#[component(test)]
struct AgentTest {
    active: Instance<TxAgent>,
    passive: Instance<TxAgent>,
    clk: Clock,
}

#[component(test)]
impl Component for AgentTest {
    type Context = Clock;

    fn build(scope: &Scope, clk: Clock) -> Result<Self, TestError> {
        let active = scope
            .create_instance::<TxAgent>("active", Config { clk, active: true }.into_context())?;
        let passive = scope.create_instance::<TxAgent>(
            "passive",
            InstanceContext::new(Config { clk, active: false }),
        )?;
        active
            .sequencer_handle()
            .set_default_sequence(Responder::new);
        log(format!(
            "active: driver {}, sequencer {}; passive: driver {}, sequencer {}",
            active.driver.is_some(),
            active.sequencer.is_some(),
            passive.driver.is_some(),
            passive.sequencer.is_some()
        ));
        Ok(AgentTest {
            active,
            passive,
            clk,
        })
    }

    async fn run(&mut self, _run_context: &mut RunContext) -> Result<(), TestError> {
        self.clk.wait(3).await;
        Ok(())
    }

    fn check(&mut self, _check_context: &mut CheckContext) {
        log(format!(
            "seen: active {:?}, passive {:?}",
            self.active.seen.borrow(),
            self.passive.seen.borrow()
        ));
    }
}

impl Test for AgentTest {
    fn setup(_setup_context: &mut SetupContext) -> Result<Clock, TestError> {
        verald_tb_runtime::testbench::registered_clock("clk")
    }
}

register_test!(AgentTest);

verald_tb_runtime::component!(Tb, Methodology);

#[test]
fn agents_make_their_parts_by_mode_and_connect_them() {
    take_log();
    let mut sim = MockSim::new();
    let mut tb = sim.build::<Tb>().unwrap();
    sim.init(&mut tb).unwrap();
    let clk = sim.clock_ref("clk");
    sim.call(&mut tb, "set_clock", &[Value::Str("clk".into()), clk])
        .unwrap();
    sim.call(&mut tb, "start", &[Value::Str("AgentTest".into())])
        .unwrap();
    sim.set_fired_clock("clk");
    for _ in 0..3 {
        sim.clock(&mut tb).unwrap();
    }
    assert!(sim.finish_requested(), "{:?}", sim.failures());
    assert!(!sim.failed(), "{:?}", sim.failures());
    assert_eq!(
        take_log(),
        [
            "active: driver true, sequencer true; passive: driver false, sequencer false",
            "drive 10",
            "drive 20",
            "drive 30",
            "seen: active [1, 2, 3], passive [1, 2, 3]",
        ]
    );
}
